import {adjustPixels,adjustmentTypes,makeSurface} from './layer-effects.js?v=20261025-release1';
const fields={brightness:[['amount','밝기',0,-100,100],['contrast','대비',0,-100,100]],hsl:[['hue','색조',0,-180,180],['saturation','채도',0,-100,100],['lightness','명도',0,-100,100]],levels:[['black','입력 검정',0,0,254],['gamma','감마',1,.1,10,.05],['white','입력 흰색',255,1,255],['outputBlack','출력 검정',0,0,255],['outputWhite','출력 흰색',255,0,255]],balance:[['red','청록 ↔ 빨강',0,-100,100],['green','자홍 ↔ 초록',0,-100,100],['blue','노랑 ↔ 파랑',0,-100,100]],posterize:[['steps','계조 수',4,2,20]],threshold:[['threshold','역치',128,0,255]]};
export function openColorCorrection(source,apply){
 const d=document.createElement('dialog');d.className='color-correction-dialog';d.setAttribute('aria-label','색조보정');
 d.innerHTML=`<style>.color-correction-dialog{width:min(860px,92vw);max-height:90vh;background:#303944;color:#e6edf4;border:1px solid #73899b;padding:20px}.cc-layout{display:grid;grid-template-columns:minmax(180px,1fr) minmax(210px,300px);gap:18px}.cc-preview{width:100%;max-height:55vh;object-fit:contain;background:repeating-conic-gradient(#66717b 0% 25%,#515d68 0% 50%) 0/16px 16px}.cc-controls{max-height:62vh;overflow:auto}.cc-controls label{display:block;margin:12px 0}.cc-controls input[type=range]{width:68%;margin-right:6px}.cc-controls input[type=number]{width:26%}.cc-graph{width:100%;touch-action:none;background:#1c2530;cursor:crosshair}.color-correction-dialog footer{display:flex;justify-content:flex-end;gap:10px;margin-top:16px}@media(max-width:600px){.cc-layout{grid-template-columns:1fr}.cc-preview{max-height:25vh}}</style><h2>색조보정</h2><p>선택한 레이어를 보정합니다. 적용하면 원본은 숨기고 보정된 새 레이어를 만듭니다.</p><div class="cc-layout"><div><canvas class="cc-preview"></canvas><label><input class="cc-before" type="checkbox">원본 비교</label></div><div class="cc-controls"><select aria-label="보정 종류"></select><div class="cc-fields"></div></div></div><p class="cc-error" role="alert"></p><footer><button class="cc-reset">초기화</button><button class="cc-cancel">취소</button><button class="cc-apply">적용</button></footer>`;
 const select=d.querySelector('select'),body=d.querySelector('.cc-fields'),preview=d.querySelector('canvas'),before=d.querySelector('.cc-before');
 for(const [k,v]of Object.entries(adjustmentTypes))select.add(new Option(v,k));
 const scale=Math.min(1,700/source.width,650/source.height);preview.width=Math.max(1,Math.round(source.width*scale));preview.height=Math.max(1,Math.round(source.height*scale));const ctx=preview.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0,preview.width,preview.height);const original=ctx.getImageData(0,0,preview.width,preview.height);let state={},graph=null,drag=-1;
 const button=(text,fn)=>{const b=document.createElement('button');b.textContent=text;b.onclick=fn;body.append(b);return b;};
 const choice=(key,title,options,value)=>{const l=document.createElement('label');l.textContent=title;const s=document.createElement('select');s.setAttribute('aria-label',title);for(const [k,v]of Object.entries(options))s.add(new Option(v,k));s.value=value;state[key]=value;s.onchange=()=>{state[key]=s.value;render();};l.append(s);body.append(l);};
 function render(){const im=new ImageData(new Uint8ClampedArray(original.data),original.width,original.height);if(!before.checked)adjustPixels(im.data,state);ctx.putImageData(im,0,0);drawGraph();}
 function drawGraph(){if(!graph)return;const g=graph.getContext('2d'),hist=new Array(256).fill(0),channel={red:0,green:1,blue:2}[state.channel];for(let i=0;i<original.data.length;i+=4){if(!original.data[i+3])continue;const v=channel===undefined?Math.round((original.data[i]+original.data[i+1]+original.data[i+2])/3):original.data[i+channel];hist[v]++;}g.clearRect(0,0,256,256);const max=Math.max(1,...hist);g.fillStyle='#526779';hist.forEach((v,x)=>g.fillRect(x,256-v/max*230,1,v/max*230));g.strokeStyle='#384b5c';for(let i=0;i<=256;i+=64){g.beginPath();g.moveTo(i,0);g.lineTo(i,256);g.moveTo(0,i);g.lineTo(256,i);g.stroke();}if(state.type!=='curves')return;g.strokeStyle='#8cd6ff';g.lineWidth=2;g.beginPath();state.points.forEach(([x,y],i)=>i?g.lineTo(x,255-y):g.moveTo(x,255-y));g.stroke();g.fillStyle='#fff';for(const [x,y]of state.points){g.beginPath();g.arc(x,255-y,4,0,Math.PI*2);g.fill();}}
 function build(){state={type:select.value};graph=null;body.replaceChildren();if(['levels','curves'].includes(state.type))choice('channel','채널',{rgb:'RGB',red:'빨강',green:'초록',blue:'파랑'},'rgb');
 for(const [key,title,value,min,max,step=1]of fields[state.type]||[]){const label=document.createElement('label');label.textContent=title;const range=document.createElement('input'),num=document.createElement('input');range.type='range';num.type='number';for(const input of [range,num]){Object.assign(input,{min,max,step,value});input.setAttribute('aria-label',title+(input===range?' 조절':''));input.oninput=()=>{if(!input.checkValidity())return;state[key]=Number(input.value);range.value=num.value=input.value;render();};}state[key]=value;label.append(range,num);body.append(label);}
 if(state.type==='balance'){choice('range','색조 범위',{all:'전체',shadows:'그림자',midtones:'중간톤',highlights:'밝은 영역'},'all');const l=document.createElement('label'),c=document.createElement('input');c.type='checkbox';c.checked=true;state.preserveLuminosity=true;c.onchange=()=>{state.preserveLuminosity=c.checked;render();};l.append(c,'명도 유지');body.append(l);}
 if(['levels','curves'].includes(state.type)){graph=makeSurface(256,256);graph.className='cc-graph';graph.setAttribute('aria-label','히스토그램 및 톤 커브');body.append(graph);if(state.type==='levels')button('자동 레벨',()=>{const h=new Array(256).fill(0),channel={red:0,green:1,blue:2}[state.channel];for(let i=0;i<original.data.length;i+=4)if(original.data[i+3])h[channel===undefined?Math.round((original.data[i]+original.data[i+1]+original.data[i+2])/3):original.data[i+channel]]++;state.black=Math.min(254,Math.max(0,h.findIndex(n=>n)));state.white=Math.min(255,Math.max(state.black+1,h.findLastIndex(n=>n)));for(const [title,key]of [['입력 검정','black'],['입력 흰색','white']])for(const el of body.querySelectorAll('input'))if(el.getAttribute('aria-label').startsWith(title))el.value=state[key];render();});else{state.points=[[0,0],[255,255]];const point=e=>{const r=graph.getBoundingClientRect();return [Math.max(0,Math.min(255,Math.round((e.clientX-r.left)*256/r.width))),Math.max(0,Math.min(255,Math.round(255-(e.clientY-r.top)*256/r.height)))];};graph.onpointerdown=e=>{const p=point(e);drag=state.points.findIndex(q=>Math.hypot(q[0]-p[0],q[1]-p[1])<14);if(drag<0){if(state.points.some(q=>q[0]===p[0]))return;state.points.push(p);state.points.sort((a,b)=>a[0]-b[0]);drag=state.points.indexOf(p);}graph.setPointerCapture(e.pointerId);render();};graph.onpointermove=e=>{if(drag<0)return;const p=point(e),pts=state.points;p[0]=drag===0?0:drag===pts.length-1?255:Math.max(pts[drag-1][0]+1,Math.min(pts[drag+1][0]-1,p[0]));pts[drag]=p;render();};graph.onpointerup=graph.onpointercancel=()=>drag=-1;const help=document.createElement('small');help.textContent='클릭하여 점 추가 · 점을 드래그하여 곡선 조절';body.append(help);}}
 if(state.type==='gradient'){state.stops=[{position:0,color:'#000000'},{position:.5,color:'#808080'},{position:1,color:'#ffffff'}];state.stops.forEach((stop,i)=>{const l=document.createElement('label');l.textContent=['어두운 영역','중간 영역','밝은 영역'][i];const c=document.createElement('input');c.type='color';c.value=stop.color;c.oninput=()=>{stop.color=c.value;render();};l.append(c);body.append(l);});}
 render();}
 select.onchange=build;before.onchange=render;d.querySelector('.cc-reset').onclick=build;d.querySelector('.cc-cancel').onclick=()=>d.close();d.querySelector('.cc-apply').onclick=async e=>{e.target.disabled=true;try{await apply(structuredClone(state));d.close();}catch(error){d.querySelector('.cc-error').textContent=error.message;e.target.disabled=false;}};d.onclose=()=>{preview.width=1;d.remove();};document.body.append(d);build();d.showModal();
}
